-- =========================================================
-- V900 — 데모 데이터 (회원·보유카드·검색기록·결제내역)
--
-- flyway.locations 에 db/seed-local 이 있는 환경(로컬·CI)에서만 적용된다.
-- 운영은 이 디렉터리를 로드하지 않는다 — 부하테스트용 AWS와 시연용 로컬은
-- 스키마가 같고 데이터가 다르다.
--
-- 번호를 900으로 크게 띄운 것은 앞으로 추가될 스키마 마이그레이션(V7, V8, ...)이
-- 항상 이 파일보다 먼저 적용되게 하려는 것이다.
--
-- 데모 페르소나 "김국민" (2026-03-04 ~ 07-25 평일 355건). 실제 혜택 규칙·전월실적·
-- 한도를 시간순으로 적용해 계산했고, 사용 카드가 최적이 아니면 놓친 혜택을 같은 행에 기록했다.
--
-- INSERT 순서는 FK 의존 순서다. 순서를 바꾸면 적재가 실패한다.
-- =========================================================

SET NAMES utf8mb4;

